#include <iostream>
#include <algorithm>
using namespace std;

using i64 = long long;

const i64 MOD = 1000000009;

i64 modPow(i64 base, i64 exp) {
    i64 result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    i64 n, m, k;
    cin >> n >> m >> k;

    i64 n1 = n / k;
    i64 freeSpaces = n - m;
    i64 rem = max(n1 - freeSpaces, 0LL);

    i64 result;
    if (rem > 0) {
        result = ((modPow(2, rem + 1) - 2 + MOD) % MOD) * (k % MOD) % MOD;
        result = (result + m % MOD - (rem % MOD) * (k % MOD) % MOD + MOD) % MOD;
    } else {
        result = m % MOD;
    }

    cout << result << '\n';
    return 0;
}

